import itertools

def get_tilings(n):
    # Returns all perfect matchings of an n x n grid
    nodes = [(i, j) for i in range(n) for j in range(n)]
    adj = {}
    for i in range(n):
        for j in range(n):
            neighbors = []
            if i > 0: neighbors.append((i-1, j))
            if i < n-1: neighbors.append((i+1, j))
            if j > 0: neighbors.append((i, j-1))
            if j < n-1: neighbors.append((i, j+1))
            adj[(i, j)] = neighbors

    def find_all_matchings(remaining_nodes, current_matching):
        if not remaining_nodes:
            yield current_matching
            return

        u = remaining_nodes[0]
        for v in adj[u]:
            if v in remaining_nodes:
                new_remaining = [node for node in remaining_nodes if node != u and node != v]
                yield from find_all_matchings(new_remaining, current_matching + (tuple(sorted((u, v))),))

    return list(find_all_matchings(nodes, ()))

def solve_for_n(n):
    tilings = get_tilings(n)
    nodes = [(i, j) for i in range(n) for j in range(n)]

    for k in range(1, n*n + 1):
        # Try all subsets of cells of size k
        for S in itertools.combinations(nodes, k):
            valid_tilings_count = 0
            for T in tilings:
                is_valid = True
                for domino in T:
                    # domino is (u, v)
                    # count how many of u, v are in S
                    marked_count = 0
                    if domino[0] in S: marked_count += 1
                    if domino[1] in S: marked_count += 1
                    if marked_count >= 2:
                        is_valid = False
                        break
                if is_valid:
                    valid_tilings_count += 1
            if valid_tilings_count == 1:
                return k
    return None

