def check_S_for_n(n, S):
    # We can't get all tilings, so we'll use a matching algorithm to count tilings.
    # But we only need to check if there is a unique tiling.
    # A unique tiling exists if and only if the grid minus the "forbidden" edges has a unique perfect matching.
    # Forbidden edges are those that connect two marked cells.
    import networkx as nx
    G = nx.grid_2d_graph(n, n)
    for u in S:
        for v in G.neighbors(u):
            if v in S:
                G.remove_edge(u, v)

    # Now we need to count perfect matchings in G.
    # For small graphs, we can use a recursive approach.
    def count_matchings(nodes, edges):
        if not nodes:
            return 1
        u = nodes[0]
        count = 0
        for v in edges[u]:
            # Try matching u with v
            new_nodes = [n for n in nodes if n != u and n != v]
            new_edges = {n: [neighbor for neighbor in neighbors if neighbor != u and neighbor != v] 
                        for n, neighbors in edges.items() if n != u and n != v}
            count += count_matchings(new_nodes, new_edges)
        return count

    nodes = list(G.nodes())
    edges = {n: list(G.neighbors(n)) for n in nodes}
    return count_matchings(nodes, edges)

